var accounts = new GlideRecord('core_company');
accounts.query();
while (accounts.next()) {
    var openIncidents = new GlideRecord('incident');
    openIncidents.addQuery('company', accounts.getUniqueValue());
    openIncidents.addQuery('active', true);
    openIncidents.query();
    gs.info(accounts.getValue('name') + ' has ' + openIncidents.getRowCount() + ' open incidents');
}

questions.modelAnswer:
This is the N+1 pattern: one query to get N companies, then one more query per company inside the loop — 501 total queries for 500 companies, scaling linearly worse as companies grow. The fix is a single query against incident, grouped in memory: query all active incidents once, build a lookup of counts keyed by company sys_id using a plain JavaScript object, then iterate companies against that in-memory map instead of querying per company. For reporting a per-company count specifically, GlideAggregate with addAggregate('COUNT') and groupBy('company') is even better, since it never pulls full row data — but the in-memory approach is the most direct fix to the exact pattern shown. The corrected version:

var counts = {};
var incidents = new GlideRecord('incident');
incidents.addQuery('active', true);
incidents.query();
while (incidents.next()) {
    var companyId = incidents.getValue('company');
    counts[companyId] = (counts[companyId] || 0) + 1;
}
var accounts = new GlideRecord('core_company');
accounts.query();
while (accounts.next()) {
    var id = accounts.getUniqueValue();
    gs.info(accounts.getValue('name') + ' has ' + (counts[id] || 0) + ' open incidents');
}

This runs exactly two queries total regardless of how many companies exist, instead of one query per company.

GlideAggregate is purpose-built for this: it computes COUNT, SUM, AVG, MIN, or MAX, grouped or ungrouped, without ever retrieving full row data for each matching record — which is exactly what a dashboard widget needs instead of looping a GlideRecord and incrementing a counter.

var ga = new GlideAggregate('incident');
ga.addQuery('active', true);
ga.addAggregate('COUNT');
ga.groupBy('priority');
ga.query();

var countsByPriority = {};
while (ga.next()) {
    var priority = ga.getValue('priority');
    var count = ga.getAggregate('COUNT');
    countsByPriority[priority] = count;
}

This runs one query total, regardless of how many open incidents exist, and returns one row per distinct priority value with its count — compared to looping every matching incident row just to tally counts, which pulls full record data for rows the widget never actually needs to display individually.

A class-based Script Include follows the standard prototype pattern: a function matching the Script Include's name, a type property set to that same name, and methods defined on the prototype so the class can be instantiated consistently and extended later if needed. For a method that will be called via GlideAjax, it should accept primitive parameters (not GlideRecord objects) since GlideAjax only passes strings across the client/server boundary.

var ApprovalUtils = Class.create();
ApprovalUtils.prototype = {
    initialize: function() {},

    isUserAuthorizedApprover: function(userId, groupId) {
        if (!userId || !groupId) {
            return false;
        }
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('user', userId);
        gr.addQuery('group', groupId);
        gr.setLimit(1);
        gr.query();
        return gr.next();
    },

    type: 'ApprovalUtils'
};

The GlideAjax-callable version would be a separate thin wrapper Script Include (extending AbstractAjaxProcessor) that calls this one, since AbstractAjaxProcessor methods must read parameters via getParameter() rather than typed arguments — ApprovalUtils itself stays reusable from both server-side script and that wrapper, rather than being tied to the Ajax-specific calling convention.

